#include <math.h>

typedef struct {
    double x, y;
} Point;

double cross(Point a, Point b, Point c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

double dot(Point a, Point b, Point c) {
    return (b.x - a.x) * (c.x - a.x) + (b.y - a.y) * (c.y - a.y);
}

int on_segment(Point a, Point b, Point p) {
    double cr = cross(a, b, p);
    if (fabs(cr) > 1e-9) return 0;
    double dotprod = dot(a, b, p);
    if (dotprod < 0) return 0;
    double len2 = (b.x - a.x)*(b.x - a.x) + (b.y - a.y)*(b.y - a.y);
    if (dotprod > len2 + 1e-9) return 0;
    return 1;
}

int point_in_polygon(Point *poly, int n, Point p) {
    int inside = 0;
    for (int i = 0, j = n-1; i < n; j = i++) {
        if (on_segment(poly[i], poly[j], p))
            return 1; // on edge
        if ((poly[i].y > p.y) != (poly[j].y > p.y)) {
            double x_intersect = (poly[j].x - poly[i].x) * (p.y - poly[i].y) 
