#define EPS 1e-9

typedef struct { double x, y; } P;

double cross(P o, P a, P b) {
    return (a.x - o.x)*(b.y - o.y) - (a.y - o.y)*(b.x - o.x);
}

double dot(P o, P a, P b) {
    return (a.x - o.x)*(b.x - o.x) + (a.y - o.y)*(b.y - o.y);
}

int onSegment(P p, P a, P b) {
    // check if p is on segment ab
    double c = cross(a, b, p); // cross of (b-a) x (p-a)
    if (fabs(c) > EPS) return 0;
    double d = dot(p, a, b); // (a-p).(b-p)
    return d <= EPS;
}

int pointInPolygon(P *poly, int n, P t) {
    // First check boundary
    for (int i = 0; i < n; i++) {
        P a = poly[i], b = poly[(i+1)%n];
        if (onSegment(t, a, b)) return 1;
    }
    // Ray casting
    int cnt = 0;
    for (int i = 0; i < n; i++) {
        P a = poly[i], b = poly[(i+1)%n];
        if ((a.y <= t.y && t.y < b.y) || (b.y <= t.y && t.y < a.y)) {
            // compute x intersection
            double x = a.x + (t.y - a.y) / (b.y - a.y) * (b.x - a.x);
            if (t.x < x) cnt++;
        }
    }
    return (cnt % 2 == 1) ? 2 : 0;
}

