typedef long long ll;

typedef struct {
    ll x, y;
} Point;

static ll cross(Point a, Point b, Point c) {
    // (b-a) x (c-a)
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

static int on_segment(Point a, Point b, Point p) {
    if (cross(a, b, p) != 0) return 0;
    if (p.x < (a.x < b.x ? a.x : b.x) || p.x > (a.x > b.x ? a.x : b.x)) return 0;
    if (p.y < (a.y < b.y ? a.y : b.y) || p.y > (a.y > b.y ? a.y : b.y)) return 0;
    return 1;
}

static int point_in_polygon(Point *poly, int n, Point p) {
    int inside = 0;

    for (int i = 0; i < n; i++) {
        Point a = poly[i];
        Point b = poly[(i + 1) % n];

        if (on_segment(a, b, p)) return 1; // boundary

        // Ray casting: count intersections with ray to +x
        int cond1 = (a.y > p.y) != (b.y > p.y);
        if (cond1) {
            ll cr = cross(a, b, p);
            // If edge crosses horizontal line through p,
            // toggle when intersection is to the right of p.
            if ((b.y > a.y && cr > 0) || (b.y < a.y && cr < 0)) {
                inside = !inside;
            }
        }
    }

    return inside ? 2 : 0;
}

