struct Point {
    double x, y;
};

// Check if point q lies on segment pr
bool onSegment(Point p, Point q, Point r) {
    if (q.x <= max(p.x, r.x) && q.x >= min(p.x, r.x) &&
        q.y <= max(p.y, r.y) && q.y >= min(p.y, r.y)) {
        // Check collinearity
        double cross = (q.x - p.x) * (r.y - p.y) - (q.y - p.y) * (r.x - p.x);
        return fabs(cross) < 1e-9;
    }
    return false;
}

// Orientation of triplet (p, q, r)
// 0 = collinear, 1 = clockwise, 2 = counterclockwise
int orientation(Point p, Point q, Point r) {
    double val = (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y);
    if (fabs(val) < 1e-9) return 0;
    return (val > 0) ? 1 : 2;
}

// Check if point t is on boundary of polygon g
bool onBoundary(const vector<Point>& g, Point t) {
    int n = g.size();
    for (int i = 0; i < n; i++) {
        int j = (i + 1) % n;
        if (onSegment(g[i], t, g[j]))
            return true;
    }
    return false;
}

// Ray casting algorithm for point in polygon
bool pointInPolygon(const vector<Point>& g, Point t) {
    int n = g.size();
    bool inside = false;
    for (int i = 0, j = n - 1; i < n; j = i++) {
        if ((g[i].y > t.y) != (g[j].y > t.y) &&
            t.x < (g[j].x - g[i].x) * (t.y - g[i].y) / (g[j].y - g[i].y) + g[i].x) {
            inside = !inside;
        }
    }
    return inside;
}

