typedef double ld;
const ld EPS = 1e-9;

struct P {
    ld x, y;
};

ld cross(P O, P A, P B) {
    return (A.x - O.x) * (B.y - O.y) - (A.y - O.y) * (B.x - O.x);
}

ld dot(P A, P B) {
    return A.x * B.x + A.y * B.y;
}

// Check if point p is on segment [a, b]
bool onSegment(P a, P b, P p) {
    // cross product of (b-a) x (p-a) == 0 and dot product check
    ld cp = (b.x - a.x) * (p.y - a.y) - (b.y - a.y) * (p.x - a.x);
    if (fabs(cp) > EPS) return false;
    // check if p is between a and b
    if (min(a.x, b.x) - EPS <= p.x && p.x <= max(a.x, b.x) + EPS &&
        min(a.y, b.y) - EPS <= p.y && p.y <= max(a.y, b.y) + EPS)
        return true;
    return false;
}

// Point in polygon using ray casting
// Returns 2 if inside, 1 if on boundary, 0 if outside
int pointInPolygon(vector<P>& poly, P p) {
    int n = poly.size();
    // First check boundary
    for (int i = 0; i < n; i++) {
        P a = poly[i], b = poly[(i+1) % n];
        if (onSegment(a, b, p)) return 1;
    }

    // Ray casting
    int cnt = 0;
    for (int i = 0; i < n; i++) {
        P a = poly[i], b = poly[(i+1) % n];
        // Ray goes in +x direction from p
        if ((a.y <= p.y && b.y > p.y) || (b.y <= p.y && a.y > p.y)) {
            // compute x intersection
            ld t = (p.y - a.y) / (b.y - a.y);
            ld xi = a.x + t * (b.x - a.x);
            if (p.x < xi) cnt++;
        }
    }
    return (cnt % 2 == 1) ? 2 : 0;
}

