using int64 = long long;

struct Point {
    int64 x, y;
};

static inline int64 cross(const Point& a, const Point& b, const Point& c) {
    // (b-a) x (c-a)
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

static inline bool onSegment(const Point& a, const Point& b, const Point& p) {
    if (cross(a, b, p) != 0) return false;
    return min(a.x, b.x) <= p.x && p.x <= max(a.x, b.x) &&
           min(a.y, b.y) <= p.y && p.y <= max(a.y, b.y);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<Point> poly(n);
    for (int i = 0; i < n; ++i) cin >> poly[i].x >> poly[i].y;

    while (m--) {
        Point q;
        cin >> q.x >> q.y;

        bool boundary = false;
        bool inside = false;

        for (int i = 0; i < n; ++i) {
            Point a = poly[i];
            Point b = poly[(i + 1) % n];

            if (onSegment(a, b, q)) {
                boundary = true;
                break;
            }

            // Ray casting to the right:
            // Count intersections of edge with horizontal ray from q.
            bool cond = (a.y > q.y) != (b.y > q.y);
            if (cond) {
                int64 cr = cross(a, b, q);
                // If edge goes upward, intersection is to the right when cr > 0
                // If edge goes downward, intersection is to the right when cr < 0
                if ((b.y > a.y && cr > 0) || (b.y < a.y && cr < 0)) {
                    inside = !inside;
                }
            }
        }

        if (boundary) cout << 1 << '\n';
        else if (inside) cout << 2 << '\n';
        else cout << 0 << '\n';
    }

    return 0;
}

