        boolean onEdge = false;
        boolean inside = false;
        for (int i = 0, j = n - 1; i < n; j = i++) {
            int xi = x[i], yi = y[i];
            int xj = x[j], yj = y[j];

            // Check if point is on the segment
            if (onSegment(px, py, xi, yi, xj, yj)) {
                return 1;
            }

            // Ray casting
            if ((yi > py) != (yj > py)) {
                long intersectX = (long)(xj - xi) * (py - yi) / (yj - yi) + xi;
                if (px == intersectX) {
                    // point lies exactly on ray intersection - treat as on edge
                    return 1;
                }
                if (px < intersectX) {
                    inside = !inside;
                }
            }
        }
        return inside ? 2 : 0;
    }

    static boolean onSegment(int px, int py, int ax, int ay, int bx, int by) {
        // Check collinearity and bounding box
        long cross = (long)(bx - ax) * (py - ay) - (long)(by - ay) * (px - ax);
        if (cross != 0) return false;
        long dot = (long)(px - ax) * (bx - ax) + (long)(py - ay) * (by - ay);
        if (dot < 0) return false;
        long sqlen = (long)(bx - ax) * (bx - ax) + (long)(by - ay) * (by - ay);
        return dot <= sqlen;
    }
}

