public class Main {
    static double EPS = 1e-9;

    static double cross(double ax, double ay, double bx, double by) {
        return ax * by - ay * bx;
    }

    static boolean onSegment(double px, double py, double ax, double ay, double bx, double by) {
        // Check if P is on segment AB
        double cx = bx - ax, cy = by - ay;
        double dx = px - ax, dy = py - ay;
        double ex = px - bx, ey = py - by;
        // cross product of AB and AP must be 0
        if (Math.abs(cross(cx, cy, dx, dy)) > EPS * Math.max(1, Math.sqrt(cx*cx+cy*cy))) return false;
        // dot products
        if (dx * cx + dy * cy < -EPS) return false;
        if (ex * (-cx) + ey * (-cy) < -EPS) return false;
        return true;
    }

    static int containsPoint(double[] px, double[] py, int n, double x, double y) {
        // Check boundary
        for (int i = 0; i < n; i++) {
            int j = (i + 1) % n;
            if (onSegment(x, y, px[i], py[i], px[j], py[j])) return 1;
        }
        // Ray casting
        int cnt = 0;
        for (int i = 0; i < n; i++) {
            int j = (i + 1) % n;
            double ax = px[i], ay = py[i], bx = px[j], by = py[j];
            if ((ay <= y && by > y) || (by <= y && ay > y)) {
                // compute x intersection
                double t = (y - ay) / (by - ay);
                double xi = ax + t * (bx - ax);
                if (xi > x) cnt++;
            }
        }
        return (cnt % 2 == 1) ? 2 : 0;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            if (n == 0) break;
            double[] px = new double[n], py = new double[n];
            for (int i = 0; i < n; i++) {
                px[i] = sc.nextDouble();
                py[i] = sc.nextDouble();
            }
            int q = sc.nextInt();
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < q; i++) {
                double x = sc.nextDouble(), y = sc.nextDouble();
                sb.append(containsPoint(px, py, n, x, y)).append('\n');
            }
            System.out.print(sb);
        }
    }
}

import java.io.*;
