public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Point {
        long x, y;
        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }

    static long cross(Point a, Point b, Point c) {
        return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    }

    static boolean onSegment(Point a, Point b, Point p) {
        if (cross(a, b, p) != 0) return false;
        return Math.min(a.x, b.x) <= p.x && p.x <= Math.max(a.x, b.x) &&
               Math.min(a.y, b.y) <= p.y && p.y <= Math.max(a.y, b.y);
    }

    static int pointInPolygon(Point[] poly, Point p) {
        int n = poly.length;

        for (int i = 0; i < n; i++) {
            Point a = poly[i];
            Point b = poly[(i + 1) % n];
            if (onSegment(a, b, p)) return 1;
        }

        boolean inside = false;
        for (int i = 0; i < n; i++) {
            Point a = poly[i];
            Point b = poly[(i + 1) % n];

            boolean cond = (a.y > p.y) != (b.y > p.y);
            if (cond) {
                long cr = cross(a, b, p);
                if (b.y > a.y) {
                    if (cr > 0) inside = !inside;
                } else {
                    if (cr < 0) inside = !inside;
                }
            }
        }

        return inside ? 2 : 0;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n = fs.nextInt();
        int m = fs.nextInt();

        Point[] poly = new Point[n];
        for (int i = 0; i < n; i++) {
            long x = fs.nextLong();
            long y = fs.nextLong();
            poly[i] = new Point(x, y);
        }

        StringBuilder out = new StringBuilder();
        for (int i = 0; i < m; i++) {
            long x = fs.nextLong();
            long y = fs.nextLong();
            int ans = pointInPolygon(poly, new Point(x, y));
            out.append(ans).append('\n');
        }

        System.out.print(out.toString());
    }
}

import sys

def on_segment(ax, ay, bx, by, px, py):
    # Check collinearity via cross product
    cross = (bx - ax) * (py - ay) - (by - ay) * (px - ax)
    if cross != 0:
        return False
    # Check bounding box
    return min(ax, bx) <= px <= max(ax, bx) and min(ay, by) <= py <= max(ay, by)

def point_in_polygon(poly, px, py):
    n = len(poly)

    # Boundary check first
    for i in range(n):
        ax, ay = poly[i]
        bx, by = poly[(i + 1) % n]
        if on_segment(ax, ay, bx, by, px, py):
            return 1

    # Ray casting / even-odd rule
    inside = False
    for i in range(n):
        ax, ay = poly[i]
        bx, by = poly[(i + 1) % n]

        # Check if edge straddles horizontal ray at y = py
        if (ay > py) != (by > py):
            # Compare x-coordinate of intersection with px without floating point
            # px < ax + (bx-ax)*(py-ay)/(by-ay)
            lhs = (px - ax) * (by - ay)
            rhs = (bx - ax) * (py - ay)

            if by > ay:
                if lhs < rhs:
                    inside = not inside
            else:
                if lhs > rhs:
                    inside = not inside

    return 2 if inside else 0

